UPDATE documentos SET datos = '{"titulo":"FeiraLab","descricion":"A Feira da Sostibilidade como laboratorio: investigación, acción e cidadanía crítica para avanzar fronte aos retos ecosociais.","nai":"","imaxe":"f-stand-alumnas","seccions":[{"id":"s16j9nd","tipo":"heroe","oculta":false,"fondo":"claro","etiqueta":"FeiraLab · Xeración Eco-Étika","titulo":"Máis ca unha feira.","destaque":"Un laboratorio permanente.","texto":"A Feira é o momento no que meses de investigación, acción e construción colectiva de cidadanía crítica se fan visibles para toda a comunidade. Detrás hai un laboratorio de innovación educativa que traballa durante todo o curso.","imaxe":"f-stand-alumnas","imaxeAlt":"Alumnas explicando o seu stand na Feira"},{"id":"fl-laboratorio","tipo":"texto_imaxe","oculta":false,"fondo":"branco","etiqueta":"A Feira como laboratorio","titulo":"Cada Feira é tamén unha pregunta de investigación.","corpo":"<p>A Feira e todo o que leva ata ela —a formación do profesorado, as investigacións do alumnado, os foros e as conferencias— funcionan tamén como un laboratorio: un espazo para estudar, coa comunidade educativa e co acompañamento da Universidade de Vigo, como avanzar fronte aos retos ecosociais.</p><p>Mentres o alumnado investiga e actúa, observamos que funciona, que dificultades aparecen e que aprendizaxes se poden levar a outros centros.</p>","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando os resultados da investigación cidadá","posicion":"dereita","botons":[]},{"id":"fl-investigacions","tipo":"cronoloxia","oculta":false,"fondo":"claro","etiqueta":"Que investigamos","titulo":"Do consumo de alimentos á cidadanía global.","fitos":[{"data":"2025 – 2026","titulo":"Que comemos nos fogares de Pontevedra e que pegada climática deixa?","texto":"Un estudo de ciencia cidadá sobre os patróns de consumo de alimentos, feito polo alumnado do IES Luís Seoane coa Universidade de Vigo e CIDEL Galicia. O alumnado recolleu enquisas en distintas zonas do concello para estimar as emisións asociadas e presentou os resultados no I Foro de Desenvolvemento Local, onde traballou con persoas do comité cidadán do clima en propostas de acción para Pontevedra. O aprendido serviu de base para deseñar SENDA 2030.","estado":"feito"},{"data":"2026 – 2027 · SENDA 2030","titulo":"Como pode a ciencia cidadá contribuír á educación para o desenvolvemento e a cidadanía global?","texto":"Unha investigación acompaña todo o camiño cara á V Feira: cuestionarios ao alumnado ao comezo e ao final do curso, rexistro das actividades e valoracións do alumnado e do profesorado. O resultado será un informe aberto, con aprendizaxes e recomendacións prácticas para os centros educativos.","estado":"agora"}]},{"id":"s17o6tx","tipo":"tarxetas","oculta":false,"fondo":"verde","etiqueta":"Como traballamos","titulo":"Tres metodoloxías que se retroalimentan.","columnas":3,"items":[{"etiqueta":"ABP · Aprendizaxe Baseada en Proxectos","titulo":"Investigar para comprender","texto":"O alumnado deseña e executa proxectos de investigación interdisciplinar sobre retos da Axenda 2030, conectando saberes científicos, sociais e artísticos."},{"etiqueta":"ApS · Aprendizaxe Servizo · CIDEL Galicia","titulo":"Actuar para transformar","texto":"O eixo que une aprendizaxe e acción comunitaria: o alumnado pon o seu coñecemento ao servizo da comunidade, con rede internacional con colectivos de Galicia e América Latina."},{"etiqueta":"CC · Ciencia cidadá · Post-Growth Innovation Lab","titulo":"Investigar con rigor e impacto real","texto":"Co acompañamento científico da Universidade de Vigo, o alumnado convértese en investigador activo e conecta o local —o barrio de Monte Porreiro— co global."}]},{"id":"s18ftlu","tipo":"tarxetas","oculta":false,"fondo":"branco","etiqueta":"Liñas de traballo","titulo":"Proxectos que moven o mundo.","texto":"O alumnado investiga en liñas temáticas conectadas cos ODS que se desenvolven ao longo do curso e culminan na Feira.","columnas":3,"items":[{"etiqueta":"ODS 7 · ODS 13","titulo":"Clima, enerxía e transición ecolóxica","texto":"Cambio climático, consumo enerxético e transición xusta: datos reais, alternativas e comunicación á comunidade."},{"etiqueta":"ODS 12","titulo":"Consumo responsable e moda sostible","texto":"O impacto da fast fashion e do consumismo, xogos educativos como Naturpoly e obradoiros de economía circular."},{"etiqueta":"ODS 10 · ODS 16","titulo":"Xustiza global e cooperación internacional","texto":"Dereitos humanos, desigualdade e solidariedade internacional, en colaboración con Oxfam Intermón e SIG Comercio Xusto."},{"etiqueta":"ODS 5","titulo":"Igualdade de xénero e diversidade","texto":"Investigación e acción sobre fendas de xénero, diversidade e inclusión, co proxecto NeoFem e o Comité UNESCO do centro."},{"etiqueta":"ODS 11","titulo":"Territorio, barrio e identidade local","texto":"Monte Porreiro como laboratorio social: mapeo comunitario e axendas políticas locais."},{"etiqueta":"ODS 2 · ODS 3","titulo":"Saúde, benestar e alimentación sostible","texto":"Alimentación ecolóxica, hortas escolares, saúde mental e benestar, con entidades como Casa Grande de Xanceda e Feitoria Verde."}]},{"id":"s19fgoj","tipo":"cronoloxia","oculta":false,"fondo":"escuro","etiqueta":"Recoñecementos","titulo":"Premios autonómicos de innovación educativa.","fitos":[{"data":"2022 · 2023","titulo":"Premio Galicons-net de Innovación Educativa en Consumo Responsable (Xunta de Galicia)","estado":"feito"},{"data":"2024","titulo":"III Premio Galego de Educación para o Desenvolvemento e a Cidadanía Global, á experiencia de Eco-Étika e o IES Luís Seoane","estado":"feito"}]},{"id":"s1a42qn","tipo":"subpaxinas","oculta":false,"fondo":"claro","etiqueta":"No laboratorio","titulo":"Máis sobre FeiraLab.","nai":"feiralab"},{"id":"s1bgiks","tipo":"chamada","oculta":false,"fondo":"morado","titulo":"Queres traer o laboratorio ao teu centro?","texto":"Escríbenos e contamos como participar na próxima Feira.","botons":[{"texto":"Participa","url":"/participa/","estilo":"principal"}]}]}', actualizado = datetime('now') WHERE coleccion = 'paxinas_libres' AND id = 'feiralab';
